wwv_flow_imp_page.create_page_validation(
 p_id=>wwv_flow_imp.id(70301327956577394926)
,p_validation_name=>'New_1'
,p_static_id=>'new-2'
,p_validation_sequence=>30
,p_validation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_count NUMBER;',
'BEGIN',
'    SELECT COUNT(*)',
'    INTO l_count',
'    FROM qa_checklist_results t',
'    WHERE t.comp = ''LP''',
'      AND t.div = :P3_DIV',
'      AND t.work_order_no = :P3_WO_NO',
'      AND t.work_order_no != 999999999999;',
'',
'    RETURN l_count = 0;',
'END;'))
,p_validation2=>'PLSQL'
,p_validation_type=>'FUNC_BODY_RETURNING_BOOLEAN'
,p_error_message=>'Work Order No already exists for COMP = ''AL'' and DIV = ''AL''.'
,p_always_execute=>'Y'
