wwv_flow_imp_page.create_page_da_action(
 p_id=>wwv_flow_imp.id(56579278615655333746)
,p_event_id=>wwv_flow_imp.id(56579278513199333745)
,p_event_result=>'TRUE'
,p_action_sequence=>10
,p_execute_on_page_init=>'N'
,p_static_id=>'native-javascript-code'
,p_action=>'NATIVE_JAVASCRIPT_CODE'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'js_code', wwv_flow_string.join(wwv_flow_t_varchar2(
    '// Get values from the page items',
    'var fromSerial = parseInt(apex.item("P3_SERIAL_NO").getValue(), 10);',
    'var toSerial = parseInt(apex.item("P3_SERIAL_NO_TO").getValue(), 10);',
    '',
    '// If either field is empty or invalid, exit',
    'if (isNaN(fromSerial) || isNaN(toSerial)) {',
    '  apex.item("P3_QTY").setValue('''');',
    '  return;',
    '}',
    '',
    '// Swap if needed',
    'if (fromSerial > toSerial) {',
    '  var temp = fromSerial;',
    '  fromSerial = toSerial;',
    '  toSerial = temp;',
    '}',
    '',
    '// Calculate how many serials are in the range (inclusive)',
    'var totalQty = (toSerial - fromSerial) + 1;',
    '',
    '// Set the total to the Qty field',
    'apex.item("P3_QTY").setValue(totalQty);')))).to_clob
,p_created_on=>wwv_flow_imp.dz('20250714084554Z')
,p_updated_on=>wwv_flow_imp.dz('20250714100245Z')
,p_created_by=>'SHINDEPRADIP325@GMAIL.COM'
,p_updated_by=>'SHINDEPRADIP325@GMAIL.COM'
);
