,p_action=>'NATIVE_JAVASCRIPT_CODE'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'js_code', wwv_flow_string.join(wwv_flow_t_varchar2(
    'var key = event.key;',
    'var input = event.target.value;',
    '',
    '// Allow only digits and control keys (Backspace, Delete, Arrow keys, Tab)',
    'if (',
    '  (key >= ''0'' && key <= ''9'') || ',
    '  key === ''Backspace'' || ',
    '  key === ''Delete'' ||',
    '  key === ''ArrowLeft'' || ',
    '  key === ''ArrowRight'' || ',
    '  key === ''Tab''',
    ') {',
    '  // Prevent more than 12 digits',
    '  if (input.length >= 12 && key >= ''0'' && key <= ''9'') {',
    '    event.preventDefault();',
    '  }',
    '} else {',
    '  event.preventDefault(); // Block all other keys including ''.''',
    '}',
    '')))).to_clob
);
end;
/
