wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(44623504540135376641)
,p_plug_name=>'Inspection Report'
,p_static_id=>'inspection-report'
,p_region_name=>'RPT_MATRIX'
,p_region_template_options=>'#DEFAULT#'
,p_plug_template=>2103954283454391425
,p_plug_display_sequence=>10
,p_plug_item_display_point=>'ABOVE'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT',
'    T.MODEL_NAME,',
'',
'    CASE',
'        WHEN T.WORK_ORDER_NO = 999999999999 THEN ''Stock Item''',
'        ELSE TO_CHAR(T.WORK_ORDER_NO)',
'    END AS WORK_ORDER_NO_S,',
'',
'    T.WORK_ORDER_NO,',
'    T.SERIAL_NO,',
'',
'    MAX(T.INSPECT_DATE) AS MODIFIED_ON,',
'    T.INSPECTED_BY,',
'    T.COMP,',
'    T.DIV,',
'',
'    (SELECT P.TYPE_NAME',
'       FROM QA_SET_TYPES P',
'      WHERE P.TYPE_ID = T.TYPE_ID) AS TYPE_ID,',
'',
'    T.TYPE_ID AS TYPEID,',
'    C.TOTAL_COUNT,',
'    C.MATCH_COUNT,',
'',
'    CASE',
'        WHEN C.TOTAL_COUNT = C.MATCH_COUNT THEN ''Completed''',
'        ELSE ''Pending''',
'    END AS PENDING_COMPLETED,',
'',
'    T.SERIAL_NO AS "modify"',
'',
'FROM QA_CHECKLIST_RESULTS T',
'',
'LEFT JOIN (',
'    SELECT',
'        MODEL_NAME,',
'        SERIAL_NO,',
'        WORK_ORDER_NO,',
'        COUNT(*) AS TOTAL_COUNT,',
'        SUM(DECODE(INSPECTED_YN, ''Y'', 1, 0)) AS MATCH_COUNT',
'    FROM QA_CHECKLIST_RESULTS',
'    GROUP BY',
'        MODEL_NAME,',
'        SERIAL_NO,',
'        WORK_ORDER_NO',
') C',
'    ON T.MODEL_NAME = C.MODEL_NAME',
'   AND T.SERIAL_NO = C.SERIAL_NO',
'   AND T.WORK_ORDER_NO = C.WORK_ORDER_NO',
'',
'WHERE T.CREATED_BY = V(''APP_USER'')',
'',
'GROUP BY',
'    T.MODEL_NAME,',
'    T.WORK_ORDER_NO,',
'    T.SERIAL_NO,',
'    T.SERIAL_NO_TO,',
'    T.INSPECTED_BY,',
'    T.COMP,',
'    T.DIV,',
'    T.TYPE_ID,',
'    C.TOTAL_COUNT,',
'    C.MATCH_COUNT',
'',
'ORDER BY MAX(T.INSPECT_DATE) DESC;'))
,p_plug_source_type=>'NATIVE_IR'
,p_plug_query_headings_type=>'COLON_DELMITED_LIST'
