,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_html  CLOB;',
'    l_count NUMBER;',
'    l_url   VARCHAR2(4000);',
'BEGIN',
'',
'    -- Pending SERIAL_NO Count',
'    SELECT COUNT(DISTINCT SERIAL_NO)',
'      INTO l_count',
'      FROM QA_CHECKLIST_RESULTS',
'     WHERE FINAL_SAVE_FLAG = ''N''',
'       AND COMP = :APP_COMP',
'       AND DIV  = :APP_DIV;',
'',
'    l_html := ''',
'',
'    <div class="ticker-wrapper">',
'',
'        <div class="ticker-label">',
'            <span class="dot"></span>',
'            <b>Alert</b>',
'        </div>',
'',
'        <div class="ticker-marquee">',
'',
'            <div class="ticker-content">',
'',
'                <span class="ticker-item">',
'',
'                    <span class="fa fa-warning u-warning-text"></span>',
'',
'                    <a href="'' || l_url || ''" class="ticker-link">',
'',
'                        <b>'' || l_count || '' Pending Inspections Available</b>',
'',
'                    </a>',
'',
'                </span>',
'',
'            </div>',
'',
'        </div>',
'',
'    </div>'';',
'',
'    RETURN l_html;',
'',
'END;'))
,p_lazy_loading=>false
,p_plug_source_type=>'NATIVE_DYNAMIC_CONTENT'
,p_created_on=>wwv_flow_imp.dz('20261016184113Z')
,p_updated_on=>wwv_flow_imp.dz('20261017054518Z')
,p_created_by=>'SHINDEPRADIP325@GMAIL.COM'
