wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(44621678437186725763)
,p_process_sequence=>20
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Check for Check List'
,p_static_id=>'check-for-check-list'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'  DELETE FROM QA_APEX_TEMP ',
'  WHERE APP_USER = :APP_USER;',
'',
'  IF :P5_REC_COUNT = 0 THEN',
'    ----------------------------------------------------------------',
unistr('    -- CASE 1: No existing results \2192 Insert base checklist /*+ IGNORE_ROW_ON_DUPKEY_INDEX(QA_APEX_TEMP QA_APEX_TEMP_CON) */'),
'    ----------------------------------------------------------------',
'    INSERT ',
'      INTO QA_APEX_TEMP (',
'        APP_USER,',
'        RESULT_ID,',
'        SR_NO,',
'        CHECKLIST_ID,',
'        CHECK_POINT,',
'        CHECK_BOX,',
'        PUMP_TYPE,',
'        MODEL,',
'        SERIAL_NO,',
' ',
'        WO_NO',
'      )',
'    SELECT ',
'        :APP_USER,',
'        NULL AS RESULT_ID,',
'        T.SR_NO,',
'        T.CHECKLIST_ID,',
'        T.CHECK_POINT,',
'        ''N'' AS CHECK_BOX,',
'        :P5_PUMP_TYPE,',
'        :P5_MODEL,',
'        :P5_SERIAL_NO,',
'        :P5_WO_NO',
'    FROM QA_CHECKLIST_MASTER T',
'    WHERE T.TYPE_ID = :P5_PUMP_TYPE',
'      AND T.IS_ACTIVE = ''Y''',
'    ORDER BY T.SR_NO;',
'',
'  ELSE',
'    ----------------------------------------------------------------',
unistr('    -- CASE 2: Existing results found \2192 Load previous inspection /*+ IGNORE_ROW_ON_DUPKEY_INDEX(QA_APEX_TEMP QA_APEX_TEMP_CON) */'),
'    ----------------------------------------------------------------',
'    INSERT ',
'      INTO QA_APEX_TEMP (',
'        APP_USER,',
'        RESULT_ID,',
'        SR_NO,',
'        CHECKLIST_ID,',
'        CHECK_POINT,',
'        CHECK_BOX,',
'        PUMP_TYPE,',
'        MODEL,',
'        SERIAL_NO,',
'        SERIAL_NO_TO,',
'        WO_NO,',
'        COMMENTS',
'      )',
'    SELECT ',
'        :APP_USER,',
'        T.RESULT_ID,',
'        T.SR_NO,',
'        T.CHECKLIST_ID,',
'        C.CHECK_POINT,',
'        T.INSPECTED_YN AS CHECK_BOX,',
'        :P5_PUMP_TYPE,',
'        :P5_MODEL,',
'        T.SERIAL_NO,',
'        T.SERIAL_NO_TO,',
'        :P5_WO_NO,',
'        T.COMMENTS',
'    FROM QA_CHECKLIST_RESULTS T',
'      JOIN QA_CHECKLIST_MASTER C ',
'        ON C.CHECKLIST_ID = T.CHECKLIST_ID',
'    WHERE T.TYPE_ID = :P5_PUMP_TYPE_HID',
'      AND T.MODEL_NAME = :P5_MODEL',
'      AND T.WORK_ORDER_NO = :P5_WO_NO',
'      AND :P5_SERIAL_NO BETWEEN T.SERIAL_NO ',
'                            AND NVL(T.SERIAL_NO_TO, T.SERIAL_NO)',
'    ORDER BY T.SR_NO;',
'',
'  END IF;',
'',
'  COMMIT;',
'END;',
''))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>230857575584036723
,p_updated_on=>wwv_flow_imp.dz('20261017055713Z')
,p_updated_by=>'SHINDEPRADIP325@GMAIL.COM'
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(44621677964224725763)
,p_process_sequence=>10
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Check for Record Exists'
,p_static_id=>'check-for-record-exists'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'    SELECT COUNT(*)',
'    INTO :P5_REC_COUNT',
'    FROM QA_CHECKLIST_RESULTS R',
'    WHERE R.MODEL_NAME    = :P5_MODEL',
'      AND R.WORK_ORDER_NO = :P5_WO_NO',
'      AND :P5_SERIAL_NO BETWEEN R.SERIAL_NO AND NVL(R.SERIAL_NO_TO, R.SERIAL_NO)',
'      AND R.COMP = :APP_COMP',
'      AND R.DIV  = :APP_DIV;',
'',
'EXCEPTION',
'    WHEN OTHERS THEN',
'        :P5_REC_COUNT := 0;',
'        DBMS_OUTPUT.PUT_LINE(''Error: '' || SQLERRM);',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>230857102622036723
,p_updated_on=>wwv_flow_imp.dz('20261016152950Z')
,p_updated_by=>'SHINDEPRADIP325@GMAIL.COM'
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(44621639986946717481)
,p_process_sequence=>40
,p_process_point=>'AFTER_SUBMIT'
,p_region_id=>wwv_flow_imp.id(44621982294009769141)
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Checklist Master - Update Records'
,p_static_id=>'checklist-master-update-records'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'  IF :P5_REC_COUNT = 0 THEN',
'    -- INSERT case',
'    BEGIN',
'      INSERT INTO QA_CHECKLIST_RESULTS (',
'        SR_NO,',
'        TYPE_ID,',
'        MODEL_NAME,',
'        WORK_ORDER_NO,',
'        SERIAL_NO,',
'        INSPECT_DATE,',
'        INSPECTED_BY,',
'        CHECKLIST_ID,',
'        INSPECTED_YN,',
'        COMMENTS,',
'        COMP,',
'        DIV,',
'        CREATED_BY,',
'        CREATED_ON',
'      )',
'      SELECT DISTINCT',
'         SR_NO,',
'        :P5_PUMP_TYPE,',
'        :P5_MODEL,',
'        :P5_WO_NO,',
'        :P5_SERIAL_NO,',
'        SYSDATE,',
'        :P5_INSPECT_BY,',
'        T.CHECKLIST_ID,',
'        T.CHECK_BOX,',
'        T.COMMENTS,',
'        :APP_COMP,',
'        :APP_DIV,',
'        v(''APP_USER''),',
'        SYSDATE',
'      FROM EDP_QA_APEX_TEMP T',
'      WHERE T.APP_USER   = v(''APP_USER'')',
'        AND T.PUMP_TYPE  = :P5_PUMP_TYPE;',
'',
'    EXCEPTION',
'      WHEN DUP_VAL_ON_INDEX THEN',
'        NULL;',
'    END;',
'',
'  ELSE',
'    -- UPDATE case',
'    UPDATE QA_CHECKLIST_RESULTS T',
'    SET ',
'      T.INSPECTED_YN = (',
'        SELECT Q.CHECK_BOX',
'        FROM QA_APEX_TEMP Q',
'        WHERE Q.APP_USER     = v(''APP_USER'')',
'          AND Q.CHECKLIST_ID = T.CHECKLIST_ID',
'          AND Q.MODEL        = T.MODEL_NAME',
'          AND Q.WO_NO        = T.WORK_ORDER_NO',
'          AND Q.SERIAL_NO    = T.SERIAL_NO',
'          AND NVL(Q.SERIAL_NO_TO, Q.SERIAL_NO) =',
'              NVL(T.SERIAL_NO_TO, T.SERIAL_NO)',
'          AND ROWNUM = 1',
'      ),',
'      T.UPDATED_BY  = v(''APP_USER''),',
'      T.UPDATED_ON  = SYSDATE',
'    WHERE EXISTS (',
'      SELECT 1',
'      FROM QA_APEX_TEMP Q',
'      WHERE Q.APP_USER     = v(''APP_USER'')',
'        AND Q.CHECKLIST_ID = T.CHECKLIST_ID',
'        AND Q.MODEL        = T.MODEL_NAME',
'        AND Q.WO_NO        = T.WORK_ORDER_NO',
'        AND Q.SERIAL_NO    = T.SERIAL_NO',
'        AND NVL(Q.SERIAL_NO_TO, Q.SERIAL_NO) =',
'            NVL(T.SERIAL_NO_TO, T.SERIAL_NO)',
'    );',
'  END IF;',
'',
'  COMMIT;',
'',
'EXCEPTION',
'  WHEN OTHERS THEN',
'    ROLLBACK;',
'    RAISE_APPLICATION_ERROR(',
'      -20001, ',
'      ''ERROR WHILE INSERT OR UPDATE: '' || SQLERRM',
'    );',
'END;',
''))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(44621675102799725760)
,p_internal_uid=>230819125344028441
,p_updated_on=>wwv_flow_imp.dz('20261017055308Z')
,p_updated_by=>'SHINDEPRADIP325@GMAIL.COM'
);
