'       T.RESULT_ID,',
'       T.SR_NO,',
'       T.CHECKLIST_ID,',
'       T.CHECK_POINT, T.CHECK_BOX as CHECK_BOX_A , T.CHECK_BOX as CHECK_BOX_B, T.CHECK_BOX as CHECK_BOX_C,',
