wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(70019424893299975122)
,p_process_sequence=>20
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Check for Check List'
,p_static_id=>'check-for-check-list'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'  DELETE FROM EDP_QA_APEX_TEMP WHERE APP_USER = :APP_USER;',
'  IF :P7_REC_COUNT = 0 THEN',
'    apex_application.g_print_success_message := ''Checklist loaded successfully.'' || :P7_REC_COUNT;',
'    INSERT INTO EDP_QA_APEX_TEMP',
'      (APP_USER,',
'       RESULT_ID,',
'       SR_NO,',
'       CHECKLIST_ID,',
'       CHECK_POINT,',
'       CHECK_BOX,',
'       PUMP_TYPE,',
'       MODEL,',
'       SERIAL_NO,',
'	     SERIAL_NO_TO,',
'       WO_NO',
'       ',
'       )',
'      SELECT :APP_USER,',
'             NULL,',
'             T.SR_NO,',
'             T.CHECKLIST_ID,',
'             T.CHECK_POINT,',
'             ''N'' AS CHECK_BOX,',
'             :P7_PUMP_TYPE,',
'             :P7_MODEL,',
'             :P7_SERIAL_NO,',
'			   :P7_SERIAL_NO_TO,',
'             :P7_WO_NO',
'        FROM QA_CHECKLIST_MASTER T',
'       where T.TYPE_ID = :P7_PUMP_TYPE_HID',
'         AND T.IS_ACTIVE = ''Y''',
'       ORDER BY T.SR_NO;',
'  ELSE',
'    apex_application.g_print_success_message := ''Checklist loaded successfully.XXXX'' || :P7_REC_COUNT;',
'    INSERT INTO EDP_QA_APEX_TEMP',
'      (APP_USER,',
'       RESULT_ID,',
'       SR_NO,',
'       CHECKLIST_ID,',
'       CHECK_POINT,',
'       CHECK_BOX,',
'       PUMP_TYPE,',
'       MODEL,',
'       SERIAL_NO,',
'	       SERIAL_NO_TO,',
'       WO_NO,COMMENTS)',
'      SELECT :APP_USER,',
'             T.RESULT_ID,',
'             T.SR_NO,',
'             T.CHECKLIST_ID,',
'             C.CHECK_POINT,',
'             T.INSPECTED_YN,',
'             :P7_PUMP_TYPE,',
'             :P7_MODEL,',
'             :P7_SERIAL_NO, ',
'			   T.SERIAL_NO_TO,',
'             :P7_WO_NO,T.COMMENTS',
'        FROM QA_CHECKLIST_RESULTS T, QA_CHECKLIST_MASTER C',
'       where T.TYPE_ID = :P7_PUMP_TYPE_HID',
'         AND T.MODEL_NAME = :P7_MODEL',
'         AND T.WORK_ORDER_NO = :P7_WO_NO',
'      --   AND T.SERIAL_NO = :P7_SERIAL_NO',
'	      AND :P7_SERIAL_NO BETWEEN T.SERIAL_NO AND NVL(T.SERIAL_NO_TO, T.SERIAL_NO)',
'         and t.comp = :P7_COMP',
'         and t.div = :P7_DIV',
'         AND C.CHECKLIST_ID = T.CHECKLIST_ID',
'       ORDER BY T.SR_NO;',
'  END IF;',
'  COMMIT;',
'END;',
''))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>70019424893299975122
,p_created_on=>wwv_flow_imp.dz('20250731130706Z')
,p_updated_on=>wwv_flow_imp.dz('20250801130409Z')
,p_created_by=>'SHINDEPRADIP325@GMAIL.COM'
,p_updated_by=>'SHINDEPRADIP325@GMAIL.COM'
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(70019424491981975121)
,p_process_sequence=>10
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Check for Record Exists'
,p_static_id=>'check-for-record-exists'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'    SELECT COUNT(*)',
'    INTO :P7_REC_COUNT',
'    FROM QA_CHECKLIST_RESULTS R',
'    WHERE R.MODEL_NAME    = :P7_MODEL',
'      AND R.WORK_ORDER_NO = :P7_WO_NO',
'      AND :P7_SERIAL_NO BETWEEN R.SERIAL_NO AND NVL(R.SERIAL_NO_TO, R.SERIAL_NO)',
'      AND R.COMP = :P7_COMP',
'      AND R.DIV  = :P7_DIV;',
'',
'EXCEPTION',
'    WHEN OTHERS THEN',
'        :P7_REC_COUNT := 0;',
'        DBMS_OUTPUT.PUT_LINE(''Error: '' || SQLERRM);',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>70019424491981975121
,p_created_on=>wwv_flow_imp.dz('20250731130706Z')
,p_updated_on=>wwv_flow_imp.dz('20250731130706Z')
,p_created_by=>'SHINDEPRADIP325@GMAIL.COM'
,p_updated_by=>'SHINDEPRADIP325@GMAIL.COM'
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(70019418172620975111)
,p_process_sequence=>20
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Checklist Master - Update Records'
,p_static_id=>'checklist-master-update-records'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'  IF :P7_REC_COUNT = 0 THEN',
'  ',
'    BEGIN',
'      INSERT INTO QA_CHECKLIST_RESULTS (',
'        SR_NO,',
'        TYPE_ID,',
'        MODEL_NAME,',
'        WORK_ORDER_NO,',
'        SERIAL_NO,',
'        SERIAL_NO_TO,  -- newly added',
'        INSPECT_DATE,',
'        INSPECTED_BY,',
'        CHECKLIST_ID,',
'        INSPECTED_YN,',
'        COMMENTS,',
'        COMP,',
'        DIV,',
'        CREATED_BY,',
'        CREATED_ON',
'      )',
'      SELECT DISTINCT',
'        SR_NO,',
'        :P7_PUMP_TYPE_HID,',
'        :P7_MODEL,',
'        :P7_WO_NO,',
'        :P7_SERIAL_NO,',
'        :P7_SERIAL_NO_TO,  -- bind value',
'        SYSDATE,',
'        :P7_INSPECT_BY,',
'        T.CHECKLIST_ID,',
'        T.CHECK_BOX,',
'        T.COMMENTS,',
'        :P7_COMP,',
'        :P7_DIV,',
'        :APP_USER,',
'        SYSDATE',
'      FROM EDP_QA_APEX_TEMP T',
'      WHERE T.APP_USER = :APP_USER',
'        AND T.PUMP_TYPE = :P7_PUMP_TYPE;',
'          apex_application.g_print_success_message := ''Checklist loaded successfully.'' || :P7_REC_COUNT;',
'    EXCEPTION',
'      WHEN DUP_VAL_ON_INDEX THEN',
'        NULL; -- Optionally log',
'    END;',
'',
'  ELSE',
'    UPDATE QA_CHECKLIST_RESULTS T',
'    SET (T.INSPECTED_YN, T.UPDATED_BY, T.UPDATED_ON) = (',
'      SELECT Q.CHECK_BOX, :APP_USER, SYSDATE',
'      FROM EDP_QA_APEX_TEMP Q',
'      WHERE Q.APP_USER       = :APP_USER',
'        AND Q.CHECKLIST_ID   = T.CHECKLIST_ID',
'        AND Q.MODEL          = T.MODEL_NAME',
'        AND Q.WO_NO          = T.WORK_ORDER_NO',
'        AND Q.SERIAL_NO      = T.SERIAL_NO',
'        AND NVL(Q.SERIAL_NO_TO, Q.SERIAL_NO) = NVL(T.SERIAL_NO_TO, T.SERIAL_NO)',
'    )',
'    WHERE EXISTS (',
'      SELECT 1',
'      FROM EDP_QA_APEX_TEMP Q',
'      WHERE Q.APP_USER       = :APP_USER',
'        AND Q.CHECKLIST_ID   = T.CHECKLIST_ID',
'        AND Q.MODEL          = T.MODEL_NAME',
'        AND Q.WO_NO          = T.WORK_ORDER_NO',
'        AND Q.SERIAL_NO      = T.SERIAL_NO',
'        AND NVL(Q.SERIAL_NO_TO, Q.SERIAL_NO) = NVL(T.SERIAL_NO_TO, T.SERIAL_NO)',
'    );',
'  END IF;',
'',
'  COMMIT;',
'',
'EXCEPTION',
'  WHEN OTHERS THEN',
'    ROLLBACK;',
'    RAISE_APPLICATION_ERROR(-20001, ''ERROR WHILE INSERT OR UPDATE: '' || SQLERRM);',
'END;',
''))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
