,p_name=>'P8_VERDICT_1'
,p_source_data_type=>'VARCHAR2'
,p_item_sequence=>60
,p_item_plug_id=>wwv_flow_imp.id(70194838861778752438)
,p_item_source_plug_id=>wwv_flow_imp.id(70194838861778752438)
,p_prompt=>'New'
,p_source=>'CHECK_BOX'
,p_display_as=>'NATIVE_RADIOGROUP'
,p_lov=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT DISTINCT ',
'    VERDICT AS D,',
'    CASE VERDICT',
'        WHEN (SELECT VERDICT_1 FROM QA_CHECKLIST_MASTER WHERE CHECKLIST_ID = :P8_CHECKLIST_ID) THEN ''A''',
'        WHEN (SELECT VERDICT_2 FROM QA_CHECKLIST_MASTER WHERE CHECKLIST_ID = :P8_CHECKLIST_ID) THEN ''B''',
'        WHEN (SELECT VERDICT_3 FROM QA_CHECKLIST_MASTER WHERE CHECKLIST_ID = :P8_CHECKLIST_ID) THEN ''C''',
'        ELSE NULL',
'    END AS R',
'FROM (',
'    SELECT VERDICT_1 AS VERDICT FROM QA_CHECKLIST_MASTER WHERE CHECKLIST_ID = :P8_CHECKLIST_ID',
'    UNION ALL',
'    SELECT VERDICT_2 FROM QA_CHECKLIST_MASTER WHERE CHECKLIST_ID = :P8_CHECKLIST_ID',
'    UNION ALL',
'    SELECT VERDICT_3 FROM QA_CHECKLIST_MASTER WHERE CHECKLIST_ID = :P8_CHECKLIST_ID',
') V',
'WHERE VERDICT IS NOT NULL',
''))
