'function generatePDF(staticId,fileName) ',
'{',
'    const element = document.getElementById(staticId);',
'    var opt = ',
'	{',
'         margin: 0,',
'         filename: fileName+".pdf",',
'         html2canvas: ',
'		 {',
'            scale: 2',
'         },',
'         jsPDF: ',
'		 {',
'			margin: 0,',
'        	unit: ''in'',',
'            format: ''a3'',',
'            orientation: ''landscape''',
'         }',
'      };',
'	  ',
'	  html2pdf().set(opt).from(element).save();',
'}',
'',
'function saveImage(imgStaticId,btnStaticId,fileName) ',
'{',
'	const element = document.getElementById(imgStaticId);',
'	const canvas = document.getElementById(btnStaticId);',
'',
'	html2canvas(element).then(',
'		function(canvas) ',
'		{',
'			const dataURL = canvas.toDataURL();',
'			const link = document.createElement("a");',
'			link.download = fileName+".png";',
'			link.href = dataURL;',
'			link.click();',
'		});',
'}',
''))
