,p_escape_on_http_output=>'N'
,p_plug_template=>2076152157930740558
,p_plug_display_sequence=>70
,p_plug_new_grid_row=>false
,p_plug_item_display_point=>'ABOVE'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT ''TOTAL SERIAL NO.'' AS CARD_TITLE, COUNT(DISTINCT SERIAL_NO) AS CARD_TEXT, ''#'' || ',
'       TO_CHAR(FLOOR(DBMS_RANDOM.VALUE(0, 255)), ''FM0X'') ||',
'       TO_CHAR(FLOOR(DBMS_RANDOM.VALUE(0, 255)), ''FM0X'') ||',
'       TO_CHAR(FLOOR(DBMS_RANDOM.VALUE(0, 255)), ''FM0X'') AS COLOR ',
'FROM (',
'  SELECT DISTINCT SERIAL_NO',
'  FROM QA_CHECKLIST_RESULTS',
'  WHERE SERIAL_NO IS NOT NULL',
')',
'UNION ALL',
'SELECT ''PENDING INSPECTIONS'', COUNT(*),''#'' || ',
'       TO_CHAR(FLOOR(DBMS_RANDOM.VALUE(0, 255)), ''FM0X'') ||',
'       TO_CHAR(FLOOR(DBMS_RANDOM.VALUE(0, 255)), ''FM0X'') ||',
'       TO_CHAR(FLOOR(DBMS_RANDOM.VALUE(0, 255)), ''FM0X'') AS COLOR ',
'FROM (',
'  SELECT DISTINCT SERIAL_NO',
'  FROM QA_CHECKLIST_RESULTS',
'  WHERE SERIAL_NO IS NOT NULL',
'  GROUP BY SERIAL_NO',
'  HAVING MIN(CASE WHEN INSPECTED_YN = ''N'' THEN 0 ELSE 1 END) = 0',
')',
'UNION ALL',
'SELECT ''COMPLETED INSPECTIONS'', COUNT(*),''#'' || ',
'       TO_CHAR(FLOOR(DBMS_RANDOM.VALUE(0, 255)), ''FM0X'') ||',
'       TO_CHAR(FLOOR(DBMS_RANDOM.VALUE(0, 255)), ''FM0X'') ||',
'       TO_CHAR(FLOOR(DBMS_RANDOM.VALUE(0, 255)), ''FM0X'') AS COLOR ',
'FROM (',
'  SELECT DISTINCT SERIAL_NO',
'  FROM QA_CHECKLIST_RESULTS',
'  WHERE SERIAL_NO IS NOT NULL',
'  GROUP BY SERIAL_NO',
'  HAVING MIN(CASE WHEN INSPECTED_YN = ''N'' THEN 0 ELSE 1 END) = 1',
')',
'UNION ALL',
'SELECT ''DEVICES'', COUNT(DISTINCT DEVICE),''#'' || ',
'       TO_CHAR(FLOOR(DBMS_RANDOM.VALUE(0, 255)), ''FM0X'') ||',
'       TO_CHAR(FLOOR(DBMS_RANDOM.VALUE(0, 255)), ''FM0X'') ||',
'       TO_CHAR(FLOOR(DBMS_RANDOM.VALUE(0, 255)), ''FM0X'') AS COLOR ',
'FROM (',
'  SELECT DISTINCT SERIAL_NO,',
'         CASE',
'           WHEN CREATED_BY = ''14458'' THEN ''Tablet 1''',
'           WHEN CREATED_BY = ''15058'' THEN ''Tablet 2''',
'           ELSE ''Other''',
'         END AS DEVICE',
'  FROM QA_CHECKLIST_RESULTS',
'  WHERE SERIAL_NO IS NOT NULL',
');',
''))
,p_lazy_loading=>false
,p_plug_source_type=>'NATIVE_CARDS'
