,p_data_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT ',
'  normalized_model_name,',
'  COUNT(DISTINCT SERIAL_NO) AS INSPECTION_COUNT,',
'  COUNT(DISTINCT SERIAL_NO) AS COUNT,',
'  MAX(MODEL_NAME) KEEP (DENSE_RANK FIRST ORDER BY MODEL_NAME) AS DISPLAY_NAME,',
'  ''#'' || ',
'    TO_CHAR(FLOOR(DBMS_RANDOM.VALUE(0, 255)), ''FM0X'') ||',
'    TO_CHAR(FLOOR(DBMS_RANDOM.VALUE(0, 255)), ''FM0X'') ||',
'    TO_CHAR(FLOOR(DBMS_RANDOM.VALUE(0, 255)), ''FM0X'') AS COLOR',
'FROM (',
'  SELECT ',
'    SERIAL_NO,',
'    MODEL_NAME,',
'    REPLACE(TRIM(MODEL_NAME), '' '', '''') AS normalized_model_name',
'  FROM QA_CHECKLIST_RESULTS',
')',
'GROUP BY normalized_model_name',
'ORDER BY INSPECTION_COUNT DESC',
'FETCH FIRST 5 ROWS ONLY;'))
,p_max_row_count=>31
,p_items_value_column_name=>'INSPECTION_COUNT'
