wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(44623306115922153452)
,p_plug_name=>'Report # 28 : Inspection Report'
,p_static_id=>'report-28-inspection-report'
,p_region_name=>'printReport'
,p_parent_plug_id=>wwv_flow_imp.id(44623409808849517044)
,p_region_template_options=>'t-Region--noBorder:t-Region--scrollBody:margin-top-md'
,p_plug_template=>4075786578761660127
,p_plug_display_sequence=>10
,p_include_in_reg_disp_sel_yn=>'Y'
,p_plug_display_point=>'SUB_REGIONS'
,p_plug_item_display_point=>'ABOVE'
,p_location=>null
,p_function_body_language=>'PLSQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_html CLOB;',
'    l_page_no NUMBER := 1;',
'    l_rows_per_page NUMBER := 18;',
'    l_current_date VARCHAR2(50) := TO_CHAR(SYSDATE, ''DD-MM-YYYY HH24:MI'');',
'    l_document_ref VARCHAR2(100);',
'    l_total_rows NUMBER := 0;',
'    l_work_order VARCHAR2(100);',
'    l_type_name VARCHAR2(100);',
'    l_serial    VARCHAR2(100);',
'BEGIN',
'    ------------------------------------------------------------------',
'    -- Work Order Number Logic',
'    ------------------------------------------------------------------',
'    SELECT CASE ',
'             WHEN :P28_WO_NO = 999999999999 THEN ''Stock Item''',
'             ELSE :P28_WO_NO ',
'           END',
'    INTO l_work_order ',
'    FROM dual;',
'    ------------------------------------------------------------------',
'    -- Document ref',
'    ------------------------------------------------------------------',
'    BEGIN',
'        SELECT T.DOCUMENT_REF INTO l_document_ref',
'        FROM QA_SET_TYPES T',
'        WHERE T.TYPE_ID = :P28_PUMP_TYPE;',
'    EXCEPTION',
'        WHEN NO_DATA_FOUND THEN',
'            l_document_ref := '' '';',
'    END;',
'',
'     BEGIN',
'        SELECT T.type_name INTO l_type_name',
'        FROM QA_SET_TYPES T',
'        WHERE T.TYPE_ID = :P28_PUMP_TYPE;',
'    EXCEPTION',
'        WHEN NO_DATA_FOUND THEN',
'            l_type_name := '' '';',
'    END;',
'',
'    ------------------------------------------------------------------',
'    -- Start HTML',
'    ------------------------------------------------------------------',
'    l_html := ''',
'    <style>',
'        .checklist-table {',
'            width: 100%;',
'            border-collapse: collapse;',
'            font-family: Arial, sans-serif;',
'        }',
'        .checklist-table th, .checklist-table td {',
'            border: 1px solid #ddd;',
'            padding: 8px;',
'        }',
'        .checklist-table th {',
'            background-color: #f2f2f2;',
'        }',
'        .page-break {',
'            page-break-before: always;',
'        }',
'        .footer-text {',
'            text-align: right;',
'            font-family: Arial, sans-serif;',
'            margin-top: 10px;',
'            font-size: 12px;',
'        }',
'        .header-block {',
'            text-align: center;',
'            font-family: Arial, sans-serif;',
'            margin-bottom: 10px;',
'        }',
'        .header-info {',
'            font-family: Arial, sans-serif;',
'            margin-bottom: 10px;',
'        }',
'    </style>',
'',
'    <div class="header-block">',
'        <h3> Inspection Report - ''|| l_type_name ||''</h3>',
'    </div>',
'',
'    <div class="header-info" style="display: flex; justify-content: space-between;">',
'        <div>',
'            <strong>Model:</strong> ''|| :P28_MODEL ||'' &nbsp;&nbsp;&nbsp;&nbsp;',
'            <strong>Order No:</strong> ''|| l_work_order ||'' &nbsp;&nbsp;&nbsp;&nbsp;',
'            <strong>Sr No:</strong> ''|| :P28_SR_NO ||''',
'        </div>',
'        <div>',
'            <strong>Date & Time:</strong> ''|| l_current_date ||''',
'        </div>',
'    </div>'';',
'',
'    ------------------------------------------------------------------',
'    -- Extra Header ONLY WHEN DIV = ''02''',
'    -----------------------------------------------------------------',
'',
'    ------------------------------------------------------------------',
'    -- Table Header',
'    ------------------------------------------------------------------',
'    l_html := l_html ||',
'    ''<table class="checklist-table">',
'        <thead>',
'            <tr>',
'                <th>Sr. No</th>',
'                <th>Check Point</th>',
'                <th>Inspected</th>',
'                <th>Comment</th>',
'            </tr>',
'        </thead>',
'        <tbody>'';',
'',
'    ------------------------------------------------------------------',
'    -- Count Rows',
'    ------------------------------------------------------------------',
'    SELECT COUNT(DISTINCT TO_NUMBER(T.SR_NO))',
'    INTO l_total_rows',
'    FROM QA_CHECKLIST_RESULTS T',
'    WHERE T.MODEL_NAME = :P28_MODEL',
'      AND T.WORK_ORDER_NO = :P28_WO_NO',
'      AND T.SERIAL_NO = :P28_SR_NO;',
'',
'    ------------------------------------------------------------------',
'    -- Row Loop',
'    ------------------------------------------------------------------',
'    FOR rec IN (',
'        SELECT DISTINCT TO_NUMBER(T.SR_NO) AS SR_NO,',
'               (SELECT M.CHECK_POINT ',
'                FROM QA_CHECKLIST_MASTER M ',
'                WHERE M.CHECKLIST_ID = T.CHECKLIST_ID) AS CHECK_POINT,',
'               T.INSPECTED_YN,',
'               T.COMMENTS',
'        FROM QA_CHECKLIST_RESULTS T',
'        WHERE T.MODEL_NAME = :P28_MODEL',
'          AND T.WORK_ORDER_NO = :P28_WO_NO',
'          AND T.SERIAL_NO = :P28_SR_NO',
'        ORDER BY 1',
'    ) LOOP',
'',
'        DBMS_LOB.APPEND(l_html, ''',
'        <tr>',
'            <td style="text-align:center;">''|| rec.SR_NO ||''</td>',
'            <td>''|| HTF.ESCAPE_SC(rec.CHECK_POINT) ||''</td>',
'            <td style="text-align:center;">',
'                <input type="checkbox" ''||',
'                    CASE WHEN rec.INSPECTED_YN = ''Y'' THEN ''checked'' ELSE '''' END ||',
'                    '' style="accent-color:#20a745;width:16px;height:16px;pointer-events:none;">',
'            </td>',
'            <td>''|| HTF.ESCAPE_SC(rec.COMMENTS) ||''</td>',
'        </tr>'');',
'',
'        -- Page Break',
'        IF l_total_rows > l_rows_per_page + 1',
'           AND MOD(rec.SR_NO, l_rows_per_page) = 0 THEN',
'',
'            DBMS_LOB.APPEND(l_html, ''',
'                </tbody>',
'                </table>',
'                <div class="page-break"></div>',
'                <table class="checklist-table">',
'                    <thead>',
'                        <tr>',
'                            <th>Sr. No</th>',
'                            <th>Check Point</th>',
'                            <th>Inspected</th>',
'                            <th>Comment</th>',
'                        </tr>',
'                    </thead>',
'                    <tbody>'');',
'        END IF;',
'    END LOOP;',
'',
'    ------------------------------------------------------------------',
'    -- Close Table + Footer',
'    ------------------------------------------------------------------',
'    DBMS_LOB.APPEND(l_html, ''',
'        </tbody>',
'        </table><br>',
'        <strong>The above mentioned product has been inspected and cleared for dispatch.</strong><br><br>',
'',
'        <div style="display:flex;justify-content:space-between;align-items:center;">',
'            <p><strong>Inspected by: ''|| :P28_INSPECT_BY ||''</strong></p>',
'            <div class="footer-text">''|| l_document_ref ||''</div>',
'        </div>',
'    '');',
'',
'    RETURN l_html;',
'END;',
''))
,p_plug_source_type=>'NATIVE_DYNAMIC_CONTENT'
,p_ajax_items_to_submit=>'P28_MODEL,P28_WO_NO,P28_INSPECT_BY,P28_PUMP_TYPE,P28_SR_NO'
,p_plug_query_headings_type=>'COLON_DELMITED_LIST'
,p_updated_on=>wwv_flow_imp.dz('20261016175753Z')
,p_updated_by=>'SHINDEPRADIP325@GMAIL.COM'
);
