 p_id=>wwv_flow_imp.id(44626516325932134543)
,p_event_id=>wwv_flow_imp.id(44626516064869134541)
,p_event_result=>'TRUE'
,p_action_sequence=>20
,p_static_id=>'native-enable'
,p_action=>'NATIVE_ENABLE'
,p_affected_elements_type=>'BUTTON'
,p_affected_button_id=>wwv_flow_imp.id(44624524484131911987)
,p_server_condition_type=>'NOT_EXISTS'
,p_server_condition_expr1=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT ',
'COUNT(*) AS TOTAL_COUNT,',
'SUM(DECODE(T.INSPECTED_YN,''Y'',1,0)) AS MATCH_COUNT',
'FROM QA_CHECKLIST_RESULTS T',
'WHERE T.MODEL_NAME  = :P28_MODEL',
