,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Download Report'
,p_static_id=>'download-report'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_context         apex_exec.t_context; ',
'    l_print_config    apex_data_export.t_print_config;',
'    l_export          apex_data_export.t_export;',
'BEGIN',
'    l_context := apex_exec.open_query_context(',
'        p_location    => apex_exec.c_location_local_db,',
'        p_sql_query   => ''SELECT ',
'    TO_NUMBER(T.SR_NO) AS SR_NO,',
'    (SELECT M.CHECK_POINT ',
'     FROM QA_CHECKLIST_MASTER M ',
'     WHERE M.CHECKLIST_ID = T.CHECKLIST_ID) AS CHECK_POINT,',
'',
'    -- For screen display using Font Awesome',
'    CASE ',
'        WHEN T.INSPECTED_YN = ''''Y'''' THEN ',
'            ''''Checked''''',
'        ELSE ',
'            NULL ',
'    END AS INSPECTION_MARK',
'FROM ',
'    QA_CHECKLIST_RESULTS T',
'WHERE ',
'    T.MODEL_NAME = '''':P28_MODEL''''',
'    AND T.WORK_ORDER_NO = :P28_WO_NO',
'    AND T.SERIAL_NO = :P28_SR_NO',
'ORDER BY ',
'    1',
''' );',
'',
'  l_print_config := apex_data_export.get_print_config(',
'    p_orientation     => apex_data_export.c_orientation_portrait,',
'    p_border_width    => 1,',
'	p_page_header		=> ''Inspection Report''',
'   ',
');',
'',
'    l_export := apex_data_export.export (',
'        p_context         => l_context,',
'        p_print_config    => l_print_config,',
'        p_format          => apex_data_export.c_format_pdf );',
'',
'    apex_exec.close( l_context );',
'',
'    apex_data_export.download( p_export => l_export );',
'',
'EXCEPTION',
'    when others THEN',
'        apex_exec.close( l_context );',
'        raise;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_type=>'NEVER'
,p_internal_uid=>232484861776464408
);
end;
